/** @param {{des: object}} api */
export default function minefill({ des, percent, math }) {
    //	The "fill" level for the mines.
    //
    //	This level is used to fill out any levels not occupied by
    //	specific levels.
    //
    des.level_init({ style: 'solidfill', fg: ' ' });

    des.level_flags('mazelevel', 'noflip');

    des.level_init({ style: 'mines', fg: '.', bg: ' ', smoothed: true, joined: true, walled: true });

    //
    des.stair('up');
    des.stair('down');
    //
    for (let i = 1, iEnd = math.random(2, 5); i <= iEnd; i++) {
        des.object('*');
    }
    des.object('(');
    for (let i = 1, iEnd = math.random(2, 4); i <= iEnd; i++) {
        des.object();
    }
    if (percent(75)) {
        for (let i = 1, iEnd = math.random(1, 2); i <= iEnd; i++) {
            des.object('boulder');
        }
    }
    //
    for (let i = 1, iEnd = math.random(6, 8); i <= iEnd; i++) {
        des.monster('gnome');
    }
    des.monster('gnome lord');
    des.monster('dwarf');
    des.monster('dwarf');
    des.monster('G');
    des.monster('G');
    des.monster(percent(50) && 'h' || 'G');
    //
    des.trap();
    des.trap();
    des.trap();
    des.trap();
    des.trap();
    des.trap();
}
